DO $exp$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Farmacología Respiratoria$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Farmacología Respiratoria$t$;
    RETURN;
  END IF;

  -- 01. Introducción al curso: farmacología respiratoria para el QF en Colombia
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El inhalador que no llega","texto":"Un paciente con asma usa su inhalador todos los días, pero la técnica es incorrecta y nunca recibe un corticoide. La farmacología respiratoria no termina en la molécula: incluye el dispositivo, la técnica y la educación. El QF puede cambiar el resultado."},"objetivos":["Reconocer el alcance de la farmacología respiratoria.","Identificar el rol del QF.","Conocer las guías de referencia.","Aplicar el contexto colombiano."],"conceptos":[{"icono":"Wind","termino":"Asma","definicion":"Inflamación variable y obstrucción reversible."},{"icono":"Activity","termino":"EPOC","definicion":"Limitación persistente del flujo aéreo."},{"icono":"Package","termino":"Dispositivo","definicion":"La técnica determina la deposición."},{"icono":"Users","termino":"Educación","definicion":"Parte del tratamiento."}],"secciones":[{"titulo":"Por qué este curso","parrafos":["La farmacología respiratoria abarca el asma, la EPOC, los dispositivos de inhalación, la rinitis alérgica, la tos, la fibrosis pulmonar y la tuberculosis. Los medicamentos inhalados son la base del tratamiento y su eficacia depende de la técnica.","El curso integra GINA 2026, GOLD 2026, las guías colombianas, las fichas técnicas del INVIMA y el contexto del PBS y MIPRES. El enfoque es aplicado, con casos y herramientas para la dispensación."]},{"titulo":"El rol del QF","parrafos":["El QF evalúa la técnica, la adherencia y la coherencia del esquema. Detecta el sobreuso de broncodilatadores de rescate, la falta de corticoide inhalado y las interacciones. También educa sobre el uso correcto y los efectos adversos.","En los programas de enfermedades respiratorias, su trabajo se mide en indicadores: técnica correcta, ICS en asma, vacunación, exacerbaciones y uso de rescate. La farmacia se convierte en un punto de intervención clínica."]},{"titulo":"Contexto colombiano","parrafos":["Las guías colombianas de asma y EPOC complementan las internacionales. El acceso a inhaladores, las combinaciones fijas y los dispositivos dependen del PBS y de la disponibilidad local. El QF verifica la cobertura y propone alternativas.","La educación debe adaptarse al nivel de alfabetización y al contexto. La técnica se enseña con demostración y se verifica en cada control."]}],"errores":[{"error":"Ver solo la receta.","correccion":"La técnica y la educación importan."},{"error":"Ignorar el acceso.","correccion":"Condiciona la adherencia."},{"error":"No demostrar la técnica.","correccion":"La explicación no basta."}],"comprueba":[{"pregunta":"¿Qué áreas cubre el curso?","respuesta":"Asma, EPOC, dispositivos, rinitis, fibrosis y TB."},{"pregunta":"¿Qué guías se usan?","respuesta":"GINA 2026 y GOLD 2026."},{"pregunta":"¿Qué aporta el QF?","respuesta":"Técnica, adherencia y seguimiento."}],"resumen":["La farmacología respiratoria es aplicada.","La técnica inhalatoria es determinante.","Las guías y el contexto colombiano se integran.","Cada clase termina en un caso."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"},{"cita":"Global Initiative for Chronic Obstructive Lung Disease. GOLD 2026 Pocket Guide. GOLD; 2025.","url":"https://goldcopd.org/2026-gold-report/"}],"imagenes":[{"ubicacion":"Introducción","descripcion":"Farmacéutico revisando un inhalador con el paciente.","alt":"Introducción a la farmacología respiratoria"}],"keywords":["farmacología respiratoria","rol químico farmacéutico","gina 2026","gold 2026"],"mapa":{"centro":"Farmacología respiratoria","ramas":[{"titulo":"Asma","icono":"Wind","nodos":["T2","ICS","MART","Biológicos"]},{"titulo":"EPOC","icono":"Activity","nodos":["LABA","LAMA","Triple"]},{"titulo":"Dispositivos","icono":"Package","nodos":["pMDI","DPI","Cámara"]},{"titulo":"Otros","icono":"Pill","nodos":["Rinitis","Tos","Fibrosis","TB"]}]},"proceso":{"titulo":"Cómo estudiar el curso","intro":"","pasos":[{"titulo":"Contextualizar","detalle":"Leer el caso y la meta.","icono":"Target","evidencia":"Meta."},{"titulo":"Comprender","detalle":"Mecanismo y dispositivo.","icono":"BookOpen","evidencia":"Notas."},{"titulo":"Aplicar","detalle":"Resolver el caso.","icono":"Workflow","evidencia":"Decisión."},{"titulo":"Verificar","detalle":"Comprobar lo aprendido.","icono":"ClipboardCheck","evidencia":"Resultado."},{"titulo":"Transferir","detalle":"Llevarlo a la práctica.","icono":"Repeat","evidencia":"Plan."}]},"caso":{"titulo":"Técnica incorrecta","contexto":"Paciente con asma que usa el inhalador a diario, sin ICS y con técnica incorrecta.","pregunta":"¿Qué revisa el QF?","opciones":[{"texto":"Solo la dosis.","correcta":false,"retro":"La técnica y el controlador importan."},{"texto":"Técnica, adherencia y falta de ICS.","correcta":true,"retro":"Aborda las causas del mal control."},{"texto":"Suspender el rescate.","correcta":false,"retro":"Necesita un plan."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción al curso: farmacología respiratoria para el QF en Colombia$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Introducción al curso: farmacología respiratoria para el QF en Colombia$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
