     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 02. Asma: inflamación T2 y no T2, hiperreactividad y obstrucción reversible
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"No todo asma es igual","texto":"Un paciente tiene asma alérgica con eosinófilos altos y otro tiene asma no T2 con obesidad. La inflamación es distinta y la respuesta al tratamiento también. Reconocer el fenotipo mejora la elección."},"objetivos":["Explicar la inflamación T2 y no T2.","Reconocer la hiperreactividad.","Diferenciar los fenotipos.","Conectar la fisiopatología con los fármacos."],"conceptos":[{"icono":"ShieldCheck","termino":"T2","definicion":"Inflamación alérgica con IL-4, IL-5 e IL-13."},{"icono":"Activity","termino":"No T2","definicion":"Neutrofílica o paucigranulocítica."},{"icono":"Wind","termino":"Hiperreactividad","definicion":"Respuesta exagerada a estímulos."},{"icono":"Repeat","termino":"Remodelado","definicion":"Cambios estructurales crónicos."}],"secciones":[{"titulo":"Inflamación T2","parrafos":["La inflamación tipo 2 se caracteriza por eosinófilos, IgE, IL-4, IL-5 e IL-13. Se asocia con atopia, alergia, pólipos nasales y buena respuesta a los corticoides inhalados y a los biológicos dirigidos a estas vías.","Los biomarcadores incluyen eosinófilos en sangre, FeNO e IgE. El fenotipo ayuda a elegir el biológico en el asma grave."]},{"titulo":"Inflamación no T2","parrafos":["La inflamación no T2 puede ser neutrofílica o paucigranulocítica. Se asocia con obesidad, tabaquismo, contaminación y algunas infecciones. La respuesta a los corticoides es menor y el manejo requiere estrategias adicionales.","La hiperreactividad bronquial y el remodelado contribuyen a la obstrucción. La obstrucción es variable y reversible, pero con el tiempo puede volverse persistente."]},{"titulo":"Consecuencias terapéuticas","parrafos":["El tratamiento base del asma es el corticoide inhalado. Los broncodilatadores alivian, pero no controlan la inflamación. En el asma grave, los biológicos se eligen según el fenotipo.","El QF revisa la adherencia, la técnica y la exposición a desencadenantes. La educación sobre la enfermedad y el plan de acción mejora el control. Los desencadenantes incluyen ácaros, polen, mascotas, moho, infecciones virales, humo, cambios de temperatura, ejercicio y estrés. La revisión de la exposición y la educación sobre el uso del inhalador son parte del manejo. En el asma ocupacional, identificar el agente es clave para evitar la progresión. La obstrucción reversible puede volverse fija con el remodelado, por lo que el control temprano es importante."]}],"errores":[{"error":"Tratar todo asma igual.","correccion":"El fenotipo importa."},{"error":"Usar solo SABA.","correccion":"Falta el controlador."},{"error":"Ignorar los desencadenantes.","correccion":"Afectan el control."}],"comprueba":[{"pregunta":"¿Qué citocinas son T2?","respuesta":"IL-4, IL-5 e IL-13."},{"pregunta":"¿Qué caracteriza la no T2?","respuesta":"Neutrófilos u obesidad."},{"pregunta":"¿Qué fármaco es la base?","respuesta":"El corticoide inhalado."}],"resumen":["El asma tiene fenotipos distintos.","La T2 responde a ICS y biológicos.","La no T2 requiere otro enfoque.","La técnica y la adherencia son clave."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"}],"imagenes":[{"ubicacion":"Fisiopatología","descripcion":"Inflamación T2 y no T2 en el asma.","alt":"Fisiopatología del asma"}],"keywords":["asma fisiopatología","inflamación t2","eosinófilos","hiperreactividad"],"mapa":{"centro":"Asma","ramas":[{"titulo":"T2","icono":"ShieldCheck","nodos":["IgE","Eosinófilos","IL-5"]},{"titulo":"No T2","icono":"Activity","nodos":["Neutrófilos","Obesidad","Humo"]},{"titulo":"Clínica","icono":"Wind","nodos":["Sibilancias","Tos","Disnea"]},{"titulo":"Fármacos","icono":"Pill","nodos":["ICS","Biológicos","Broncodilatadores"]}]},"proceso":{"titulo":"Reconocer el fenotipo","intro":"","pasos":[{"titulo":"Clínica","detalle":"Síntomas y desencadenantes.","icono":"Wind","evidencia":"Entrevista."},{"titulo":"Biomarcadores","detalle":"Eosinófilos y FeNO.","icono":"TestTube","evidencia":"Laboratorio."},{"titulo":"Fenotipo","detalle":"T2 o no T2.","icono":"Search","evidencia":"Juicio."},{"titulo":"Tratar","detalle":"ICS y biológico si aplica.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Seguir","detalle":"Control y adherencia.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Asma alérgica","contexto":"Paciente con rinitis, IgE alta, eosinófilos elevados y síntomas estacionales.","pregunta":"¿Qué fenotipo predomina?","opciones":[{"texto":"T2 alérgico.","correcta":true,"retro":"Responde a ICS y biológicos T2."},{"texto":"No T2 neutrofílico.","correcta":false,"retro":"Los biomarcadores no lo sugieren."},{"texto":"Asma ocupacional.","correcta":false,"retro":"No hay datos de exposición laboral."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Asma: inflamación T2 y no T2, hiperreactividad y obstrucción reversible$t$ AND deleted_at IS NULL
