  -- 03. EPOC: inflamación neutrofílica, limitación persistente del flujo aéreo y diferencias con el asma
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Parecida, pero no igual","texto":"La EPOC y el asma comparten síntomas, pero difieren en la inflamación, la reversibilidad y el tratamiento. Confundirlas lleva a tratamientos inadecuados. La espirometría y la historia ayudan a diferenciarlas."},"objetivos":["Explicar la fisiopatología de la EPOC.","Diferenciarla del asma.","Reconocer las dianas terapéuticas.","Aplicar el enfoque clínico."],"conceptos":[{"icono":"Activity","termino":"Neutrófilos","definicion":"Inflamación predominante."},{"icono":"Wind","termino":"Enfisema","definicion":"Destrucción alveolar."},{"icono":"Bug","termino":"Bronquitis","definicion":"Tos y expectoración crónicas."},{"icono":"LineChart","termino":"FEV1/FVC","definicion":"Obstrucción persistente."}],"secciones":[{"titulo":"Fisiopatología","parrafos":["La EPOC se caracteriza por inflamación neutrofílica, destrucción del parénquima (enfisema) y enfermedad de la vía aérea pequeña. La limitación del flujo aéreo es persistente y a menudo progresiva. El tabaco y la biomasa son los principales factores de riesgo.","La disnea, la tos y la expectoración son los síntomas principales. Las exacerbaciones aceleran la pérdida de función y empeoran el pronóstico."]},{"titulo":"Diferencias con el asma","parrafos":["El asma suele iniciar en la juventud, se asocia con atopia y tiene obstrucción variable. La EPOC aparece en adultos con exposición y tiene obstrucción persistente. La reversibilidad no siempre separa ambas, y algunos pacientes presentan rasgos de las dos.","En el asma, el corticoide inhalado es la base. En la EPOC, la base son los broncodilatadores de acción prolongada y el ICS se reserva para exacerbadores con eosinófilos elevados."]},{"titulo":"Consecuencias","parrafos":["La elección del tratamiento depende de los síntomas, las exacerbaciones y los eosinófilos. La rehabilitación pulmonar, la vacunación y la cesación tabáquica son parte del manejo.","El QF revisa la técnica, la adherencia y el uso de rescate. También detecta fármacos que empeoran la enfermedad y educa sobre el autocuidado. La EPOC se asocia con comorbilidades cardiovasculares, osteoporosis, ansiedad, depresión y cáncer de pulmón. La evaluación integral y la rehabilitación mejoran la calidad de vida. Las exacerbaciones se previenen con vacunación, cesación tabáquica y tratamiento optimizado. La espirometría posbroncodilatador es obligatoria para el diagnóstico y la clasificación."]}],"errores":[{"error":"Confundir EPOC con asma.","correccion":"El tratamiento difiere."},{"error":"Usar ICS en todos.","correccion":"Se reserva para perfiles específicos."},{"error":"No revisar la técnica.","correccion":"Afecta el control."}],"comprueba":[{"pregunta":"¿Qué inflamación predomina?","respuesta":"La neutrofílica."},{"pregunta":"¿Qué es enfisema?","respuesta":"Destrucción alveolar."},{"pregunta":"¿Cuándo se usa ICS?","respuesta":"Con exacerbaciones y eosinófilos elevados."}],"resumen":["La EPOC es persistente y progresiva.","La inflamación es neutrofílica.","El tratamiento base son los broncodilatadores.","La EPOC y el asma pueden superponerse."],"referencias":[{"cita":"Global Initiative for Chronic Obstructive Lung Disease. GOLD 2026 Pocket Guide. GOLD; 2025.","url":"https://goldcopd.org/2026-gold-report/"}],"imagenes":[{"ubicacion":"Fisiopatología","descripcion":"Enfisema y bronquitis crónica.","alt":"Fisiopatología de la EPOC"}],"keywords":["epoc fisiopatología","enfisema","bronquitis crónica","neutrófilos"],"mapa":{"centro":"EPOC","ramas":[{"titulo":"Fenotipos","icono":"Activity","nodos":["Enfisema","Bronquitis","Exacerbador"]},{"titulo":"Inflamación","icono":"Bug","nodos":["Neutrófilos","Macrófagos","Estrés"]},{"titulo":"Diferencia","icono":"LineChart","nodos":["Persistente","Tabaquismo","Eosinófilos"]},{"titulo":"Fármacos","icono":"Pill","nodos":["LABA","LAMA","ICS"]}]},"proceso":{"titulo":"Diferenciar y tratar","intro":"","pasos":[{"titulo":"Historia","detalle":"Inicio y exposición.","icono":"Users","evidencia":"Entrevista."},{"titulo":"Espirometría","detalle":"Obstrucción persistente.","icono":"LineChart","evidencia":"Informe."},{"titulo":"Fenotipo","detalle":"Síntomas y exacerbaciones.","icono":"ClipboardList","evidencia":"Evaluación."},{"titulo":"Tratar","detalle":"LABA+LAMA ± ICS.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Seguir","detalle":"Técnica y exacerbaciones.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Fumador con disnea","contexto":"Hombre de 62 años, fumador, con disnea progresiva y FEV1/FVC de 0,62.","pregunta":"¿Qué diagnóstico es más probable?","opciones":[{"texto":"EPOC.","correcta":true,"retro":"Exposición y obstrucción persistente."},{"texto":"Asma alérgica.","correcta":false,"retro":"No hay atopia ni variabilidad."},{"texto":"Neumonía.","correcta":false,"retro":"El cuadro es crónico."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$EPOC: inflamación neutrofílica, limitación persistente del flujo aéreo y diferencias con el asma$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$EPOC: inflamación neutrofílica, limitación persistente del flujo aéreo y diferencias con el asma$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
