  END IF;

  -- 04. Agonistas beta-2: SABA y LABA (salbutamol, formoterol, salmeterol, vilanterol, indacaterol, olodaterol)
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Aliviar no es controlar","texto":"El salbutamol alivia en minutos, pero no trata la inflamación. Los LABA mantienen el bronquio abierto, pero en asma nunca van solos. Conocer el perfil de cada beta-2 evita errores."},"objetivos":["Diferenciar SABA y LABA.","Aplicar sus indicaciones.","Reconocer efectos adversos.","Educar sobre el sobreuso."],"conceptos":[{"icono":"Zap","termino":"SABA","definicion":"Alivio rápido; salbutamol."},{"icono":"Timer","termino":"LABA","definicion":"Mantenimiento; 12 o 24 horas."},{"icono":"AlertTriangle","termino":"Sobreuso","definicion":"Indica mal control."},{"icono":"Pill","termino":"Formoterol","definicion":"Inicio rápido; permite rescate con ICS."}],"secciones":[{"titulo":"SABA y LABA","parrafos":["Los agonistas beta-2 de acción corta, como el salbutamol, alivian la broncoconstricción en minutos. Los de acción prolongada, como formoterol, salmeterol, vilanterol, indacaterol y olodaterol, mantienen el bronquio abierto durante 12 o 24 horas y se usan de mantenimiento.","El formoterol tiene inicio rápido y puede usarse como rescate cuando se combina con un corticoide inhalado. El salmeterol no se usa como rescate. En asma, un LABA nunca debe usarse sin ICS."]},{"titulo":"Seguridad","parrafos":["Los efectos adversos incluyen temblor, taquicardia, cefalea e hipopotasemia con dosis altas. El sobreuso de SABA se asocia con exacerbaciones y muerte. Usar más de dos veces por semana, sin contar el ejercicio, obliga a reevaluar.","Los betabloqueantes no selectivos pueden antagonizar el efecto y causar broncoespasmo. El QF revisa la técnica, el uso de rescate y la adherencia al controlador. La hipopotasemia es más frecuente con dosis altas y con la combinación de beta-2, corticoides y diuréticos; se vigila en pacientes con cardiopatía o tratamiento con digoxina. El temblor y la taquicardia suelen mejorar con el uso continuado, pero pueden afectar la adherencia. La educación debe explicar la diferencia entre el inhalador de alivio y el de mantenimiento, y la importancia de no aumentar el rescate sin consultar."]},{"titulo":"Elección","parrafos":["En asma, la vía 1 de GINA usa ICS-formoterol como rescate y mantenimiento. En EPOC, LABA y LAMA son la base. La elección depende de la enfermedad, el dispositivo y la cobertura.","La educación diferencia el rescate del mantenimiento y explica los límites. La revisión periódica del uso de SABA es un indicador de control."]}],"errores":[{"error":"Usar LABA solo en asma.","correccion":"Siempre con ICS."},{"error":"No contar el rescate.","correccion":"Es un indicador de control."},{"error":"Ignorar el temblor.","correccion":"Puede afectar la adherencia."}],"comprueba":[{"pregunta":"¿Qué LABA tiene inicio rápido?","respuesta":"Formoterol."},{"pregunta":"¿Cuándo reevaluar?","respuesta":"Más de 2 veces por semana."},{"pregunta":"¿Con qué no se combina?","respuesta":"Betabloqueantes no selectivos."}],"resumen":["SABA alivia; LABA mantiene.","En asma, LABA siempre con ICS.","El sobreuso es una señal de riesgo.","La técnica y la educación son clave."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"},{"cita":"AEMPS-CIMA. Ficha técnica de Salbutamol Sandoz 100 microgramos/dosis. Revisión mayo 2024.","url":"https://cima.aemps.es/cima/dochtml/ft/70869/FT_70869.html"}],"imagenes":[{"ubicacion":"Broncodilatadores","descripcion":"SABA y LABA con sus perfiles.","alt":"Agonistas beta-2 SABA y LABA"}],"keywords":["saba","laba","salbutamol","formoterol","sobreuso"],"mapa":{"centro":"Beta-2","ramas":[{"titulo":"SABA","icono":"Zap","nodos":["Salbutamol","Alivio","Máximo 8/día"]},{"titulo":"LABA","icono":"Timer","nodos":["Formoterol","Salmeterol","Vilanterol"]},{"titulo":"Asma","icono":"ShieldCheck","nodos":["Con ICS","MART","No solos"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Temblor","Taquicardia","Potasio"]}]},"proceso":{"titulo":"Checklist beta-2","intro":"","pasos":[{"titulo":"Enfermedad","detalle":"Asma o EPOC.","icono":"Target","evidencia":"Diagnóstico."},{"titulo":"Tipo","detalle":"SABA o LABA.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Combinación","detalle":"Con ICS en asma.","icono":"Layers","evidencia":"Esquema."},{"titulo":"Técnica","detalle":"Dispositivo y uso.","icono":"Eye","evidencia":"Demostración."},{"titulo":"Seguir","detalle":"Rescate y efectos.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"SABA diario","contexto":"Paciente con asma que usa salbutamol todos los días sin ICS.","pregunta":"¿Qué significa?","opciones":[{"texto":"Asma no controlada; requiere ICS.","correcta":true,"retro":"El rescate no trata la inflamación."},{"texto":"Está bien controlado.","correcta":false,"retro":"El uso diario indica riesgo."},{"texto":"Necesita más salbutamol.","correcta":false,"retro":"No resuelve la causa."}]}}$j$::jsonb;
