  -- 05. Antimuscarínicos: SAMA y LAMA (ipratropio, tiotropio, glicopirronio, umeclidinio, aclidinio)
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La boca seca que avisa","texto":"El tiotropio mejora la disnea, pero puede causar boca seca y retención urinaria. Los antimuscarínicos son eficaces, pero exigen revisar glaucoma y próstata. La seguridad es parte de la elección."},"objetivos":["Diferenciar SAMA y LAMA.","Aplicar sus indicaciones.","Reconocer efectos adversos.","Revisar la técnica del dispositivo."],"conceptos":[{"icono":"Wind","termino":"SAMA","definicion":"Ipratropio; acción corta."},{"icono":"Timer","termino":"LAMA","definicion":"Tiotropio y otros; 24 horas."},{"icono":"AlertTriangle","termino":"Retención","definicion":"Riesgo urinario y ocular."},{"icono":"Layers","termino":"Combinación","definicion":"LABA+LAMA en EPOC."}],"secciones":[{"titulo":"Mecanismo y uso","parrafos":["Los antimuscarínicos bloquean los receptores muscarínicos y reducen el tono broncoconstrictor. El ipratropio es de acción corta y se añade al SABA en crisis. Los LAMA, como tiotropio, glicopirronio, umeclidinio y aclidinio, se usan de mantenimiento en EPOC y en asma grave seleccionada.","En EPOC, LABA+LAMA es una combinación inicial frecuente. En asma, el LAMA se añade en pasos avanzados y no sustituye al ICS."]},{"titulo":"Seguridad","parrafos":["Los efectos adversos incluyen boca seca, estreñimiento, retención urinaria, glaucoma de ángulo cerrado y visión borrosa. Se usan con precaución en hiperplasia prostática, glaucoma y enfermedad renal avanzada. El contacto con los ojos debe evitarse.","El QF revisa la técnica del dispositivo, la limpieza y la adherencia. La educación sobre los síntomas de alarma es parte de la dispensación. La boca seca es el efecto más frecuente y puede reducir la adherencia; se recomienda hidratación y revisiones odontológicas. En pacientes con glaucoma, el contacto con la niebla del dispositivo debe evitarse. La revisión de la función renal es importante para el tiotropio, que se elimina por vía renal. El QF verifica que el paciente no duplique anticolinérgicos y que la técnica sea correcta."]},{"titulo":"Elección","parrafos":["La elección depende de la enfermedad, el dispositivo y la cobertura. La combinación con LABA simplifica el esquema y mejora la adherencia. El QF verifica la coherencia y la técnica.","La revisión periódica de los síntomas y de los efectos adversos permite ajustar el tratamiento."]}],"errores":[{"error":"No revisar glaucoma.","correccion":"Puede agravar."},{"error":"Usar LAMA en crisis.","correccion":"No es de rescate."},{"error":"No enseñar la técnica.","correccion":"La dosis no llega."}],"comprueba":[{"pregunta":"¿Qué hace el ipratropio?","respuesta":"Bloqueo muscarínico de acción corta."},{"pregunta":"¿Qué combinación es frecuente en EPOC?","respuesta":"LABA+LAMA."},{"pregunta":"¿Qué efectos vigilar?","respuesta":"Sequedad, retención y glaucoma."}],"resumen":["SAMA y LAMA reducen el tono bronquial.","El LAMA es mantenimiento.","La seguridad ocular y urinaria importa.","La técnica y la adherencia son clave."],"referencias":[{"cita":"Global Initiative for Chronic Obstructive Lung Disease. GOLD 2026 Pocket Guide. GOLD; 2025.","url":"https://goldcopd.org/2026-gold-report/"},{"cita":"AEMPS-CIMA. Ficha técnica de Spiriva Respimat 2,5 microgramos. Revisión diciembre 2024.","url":"https://cima.aemps.es/cima/dochtml/ft/69589/FT_69589.html"}],"imagenes":[{"ubicacion":"Antimuscarínicos","descripcion":"SAMA y LAMA con sus precauciones.","alt":"Antimuscarínicos SAMA y LAMA"}],"keywords":["ipratropio","tiotropio","lama","antimuscarínicos"],"mapa":{"centro":"Antimuscarínicos","ramas":[{"titulo":"SAMA","icono":"Wind","nodos":["Ipratropio","Crisis","Añadido"]},{"titulo":"LAMA","icono":"Timer","nodos":["Tiotropio","Glicopirronio","Umeclidinio"]},{"titulo":"Uso","icono":"Target","nodos":["EPOC","Asma grave","Combinación"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Ojos","Próstata","Sequedad"]}]},"proceso":{"titulo":"Checklist antimuscarínico","intro":"","pasos":[{"titulo":"Indicación","detalle":"EPOC o asma grave.","icono":"Target","evidencia":"Diagnóstico."},{"titulo":"Tipo","detalle":"SAMA o LAMA.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Seguridad","detalle":"Ojos y próstata.","icono":"AlertTriangle","evidencia":"Revisión."},{"titulo":"Técnica","detalle":"Dispositivo.","icono":"Eye","evidencia":"Demostración."},{"titulo":"Seguir","detalle":"Síntomas y adherencia.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Glaucoma y tiotropio","contexto":"Paciente con EPOC y glaucoma de ángulo cerrado al que le formulan tiotropio.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Dispensar sin revisar.","correcta":false,"retro":"Hay una precaución importante."},{"texto":"Comunicar y reforzar el cuidado ocular.","correcta":true,"retro":"Se evalúa el riesgo."},{"texto":"Duplicar la dosis.","correcta":false,"retro":"Nunca."}]}}$j$::jsonb;
