  -- 06. Corticosteroides inhalados y sistémicos: potencia, dosis bajas/medias/altas y seguridad
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El corticoide que no se suspende","texto":"En asma, el corticoide inhalado es la base y no debe suspenderse por completo en adultos. En EPOC, se reserva para exacerbadores con eosinófilos altos. Conocer la potencia y la seguridad evita errores."},"objetivos":["Diferenciar los corticoides.","Aplicar dosis y potencia.","Reconocer efectos locales y sistémicos.","Revisar interacciones."],"conceptos":[{"icono":"ShieldCheck","termino":"ICS","definicion":"Base del asma."},{"icono":"Pill","termino":"Potencia","definicion":"Budesonida, fluticasona y otros."},{"icono":"AlertTriangle","termino":"Neumonía","definicion":"Riesgo del ICS en EPOC."},{"icono":"Network","termino":"CYP3A4","definicion":"Inhibidores aumentan la exposición."}],"secciones":[{"titulo":"Inhalados","parrafos":["Los corticoides inhalados reducen la inflamación de la vía aérea. En asma son la base del tratamiento y se usan en todos los pasos. En EPOC se reservan para pacientes con exacerbaciones y eosinófilos elevados, y aumentan el riesgo de neumonía.","La potencia y la dosis varían entre moléculas. La dosis baja, media o alta depende del fármaco y del dispositivo. La titulación busca el control con la menor dosis."]},{"titulo":"Seguridad","parrafos":["Los efectos locales incluyen candidiasis oral, disfonía e irritación de garganta. El enjuague después de la dosis reduce el riesgo. Los efectos sistémicos con dosis altas o uso prolongado incluyen osteoporosis, cataratas, glaucoma, hiperglucemia y supresión suprarrenal.","Los inhibidores potentes del CYP3A4 aumentan la exposición sistémica y deben revisarse. En EPOC, la neumonía es el riesgo más relevante."]},{"titulo":"Uso seguro","parrafos":["El ICS no se inicia durante una exacerbación grave y no se suspende bruscamente. La técnica y el enjuague son parte de la dispensación. El QF revisa la dosis, la indicación y las interacciones.","La educación sobre el propósito del ICS y los efectos adversos mejora la adherencia. La revisión periódica permite ajustar. La dosis se ajusta según el control y el riesgo. En asma, la reducción se hace después de dos a tres meses de buen control, sin suspender por completo. En EPOC, la retirada del ICS se considera si no hay exacerbaciones y los eosinófilos son bajos. El QF documenta la dosis, la técnica y los efectos adversos, y educa sobre la diferencia entre el corticoide inhalado y el sistémico."]}],"errores":[{"error":"No indicar enjuague.","correccion":"Candidiasis y disfonía."},{"error":"Usar ICS en EPOC sin criterios.","correccion":"Riesgo de neumonía."},{"error":"Suspender bruscamente.","correccion":"Riesgo de exacerbación."}],"comprueba":[{"pregunta":"¿Dónde se usa el ICS?","respuesta":"Asma y EPOC seleccionada."},{"pregunta":"¿Qué efectos locales hay?","respuesta":"Candidiasis y disfonía."},{"pregunta":"¿Qué interacción es clave?","respuesta":"Inhibidores del CYP3A4."}],"resumen":["El ICS es la base del asma.","En EPOC se usa con criterios.","El enjuague reduce efectos locales.","Los inhibidores del CYP3A4 importan."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"},{"cita":"AEMPS-CIMA. Ficha técnica de Symbicort Turbuhaler 160/4,5 microgramos. Revisión febrero 2021.","url":"https://cima.aemps.es/cima/dochtml/ft/63958/FT_63958.html"}],"imagenes":[{"ubicacion":"Corticoides","descripcion":"Dosis y seguridad de los corticoides.","alt":"Corticosteroides inhalados y sistémicos"}],"keywords":["corticoides inhalados","ics asma","ics epoc","candidiasis"],"mapa":{"centro":"Corticoides","ramas":[{"titulo":"Inhalados","icono":"ShieldCheck","nodos":["Budesonida","Fluticasona","Mometasona"]},{"titulo":"Dosis","icono":"Pill","nodos":["Baja","Media","Alta"]},{"titulo":"Locales","icono":"AlertTriangle","nodos":["Candidiasis","Disfonía"]},{"titulo":"Sistémicos","icono":"Activity","nodos":["Hueso","Glucosa","Catarata"]}]},"proceso":{"titulo":"Checklist de ICS","intro":"","pasos":[{"titulo":"Indicación","detalle":"Asma o EPOC con criterios.","icono":"Target","evidencia":"Diagnóstico."},{"titulo":"Dosis","detalle":"Baja, media o alta.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Técnica","detalle":"Enjuague y dispositivo.","icono":"Eye","evidencia":"Demostración."},{"titulo":"Interacción","detalle":"CYP3A4.","icono":"Network","evidencia":"Lista."},{"titulo":"Seguir","detalle":"Adversos y control.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Candidiasis oral","contexto":"Paciente con ICS que presenta placas blancas en la boca.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Indicar el enjuague y revisar la técnica.","correcta":true,"retro":"Reduce la candidiasis."},{"texto":"Duplicar la dosis.","correcta":false,"retro":"Empeora."},{"texto":"Suspender el ICS sin consultar.","correcta":false,"retro":"Riesgo de exacerbación."}]}}$j$::jsonb;
