  -- 07. Caso clínico: sobreuso de SABA y corticofobia en una paciente con asma
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El miedo al corticoide","texto":"Una paciente usa salbutamol a diario y evita el corticoide porque teme engordar. El sobreuso y la corticofobia perpetúan el mal control. La educación y una estrategia antiinflamatoria cambian el pronóstico."},"objetivos":["Reconocer el sobreuso y la corticofobia.","Aplicar la estrategia antiinflamatoria.","Corregir la técnica.","Diseñar educación y seguimiento."],"conceptos":[{"icono":"AlertTriangle","termino":"Sobreuso","definicion":"Rescate diario o excesivo."},{"icono":"ShieldCheck","termino":"Corticofobia","definicion":"Miedo infundado al ICS."},{"icono":"Users","termino":"Educación","definicion":"Explicar beneficios y riesgos."},{"icono":"Pill","termino":"AIR","definicion":"Rescate antiinflamatorio."}],"secciones":[{"titulo":"Evaluación","parrafos":["La paciente usa salbutamol a diario y no tiene corticoide inhalado. Refiere miedo a los corticoides por el peso y los efectos adversos. Se evalúan el control, la técnica, la frecuencia de rescate y las exacerbaciones.","El QF explora las creencias y explica la diferencia entre el corticoide inhalado y el sistémico. La corticofobia es una barrera frecuente y tratable."]},{"titulo":"Intervención","parrafos":["Se propone una estrategia con corticoide inhalado, idealmente ICS-formoterol como rescate antiinflamatorio según la vía 1 de GINA, y se corrige la técnica. Se explica que el ICS local tiene menos efectos sistémicos que el corticoide oral.","Se acuerda un plan de acción y un control en cuatro semanas. La educación incluye el uso del rescate y los límites."]},{"titulo":"Seguimiento","parrafos":["Se evalúan el ACT, el uso de rescate, la adherencia y la técnica. La reducción del rescate y la mejoría del control indican éxito. La revisión refuerza la confianza en el tratamiento.","El caso muestra que la educación y la estrategia antiinflamatoria son intervenciones clínicas, no solo informativas. La intervención debe incluir una revisión de la técnica con demostración, un plan escrito y un control cercano. La reducción del rescate y la mejoría del ACT son indicadores de éxito. Si la paciente sigue con síntomas, se revisa la adherencia y se considera escalar el tratamiento. La comunicación con el médico tratante permite ajustar el esquema sin perder continuidad. La educación debe repetirse en cada contacto. La revisión de la técnica y del uso de rescate debe hacerse en cada visita."]}],"errores":[{"error":"No explorar creencias.","correccion":"La corticofobia persiste."},{"error":"No corregir la técnica.","correccion":"El ICS no llega."},{"error":"No medir el rescate.","correccion":"No se evalúa el impacto."}],"comprueba":[{"pregunta":"¿Qué es corticofobia?","respuesta":"Miedo infundado al corticoide."},{"pregunta":"¿Qué estrategia se usa?","respuesta":"ICS o AIR según la vía."},{"pregunta":"¿Cómo se evalúa?","respuesta":"ACT, rescate y técnica."}],"resumen":["El sobreuso y la corticofobia son barreras.","La educación aborda las creencias.","El ICS es la base del asma.","El seguimiento mide el impacto."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"}],"imagenes":[{"ubicacion":"Caso","descripcion":"Paciente con sobreuso de SABA y corticofobia.","alt":"Caso de sobreuso de SABA"}],"keywords":["sobreuso saba","corticofobia","asma","air"],"mapa":{"centro":"Sobreuso y corticofobia","ramas":[{"titulo":"Datos","icono":"Calculator","nodos":["Inhaladores","Días/mes","Síntomas"]},{"titulo":"Miedo","icono":"AlertTriangle","nodos":["Peso","Efectos","Creencias"]},{"titulo":"Estrategia","icono":"ShieldCheck","nodos":["ICS","AIR","Técnica"]},{"titulo":"Seguimiento","icono":"CalendarClock","nodos":["ACT","Rescate","Adherencia"]}]},"proceso":{"titulo":"Abordar el caso","intro":"","pasos":[{"titulo":"Cuantificar","detalle":"Rescate y síntomas.","icono":"Calculator","evidencia":"Historial."},{"titulo":"Explorar","detalle":"Creencias y miedos.","icono":"Users","evidencia":"Entrevista."},{"titulo":"Educar","detalle":"ICS y técnica.","icono":"GraduationCap","evidencia":"Consejería."},{"titulo":"Tratar","detalle":"AIR y plan.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Seguir","detalle":"ACT y rescate.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Miedo al ICS","contexto":"Paciente con asma que usa SABA diario y rechaza el ICS por miedo al peso.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Insistir sin explicar.","correcta":false,"retro":"No aborda la barrera."},{"texto":"Explicar beneficios y proponer ICS.","correcta":true,"retro":"Aborda la corticofobia."},{"texto":"Aumentar el SABA.","correcta":false,"retro":"Empeora el riesgo."}]}}$j$::jsonb;
