  -- 08. Introducción a la unidad: del SABA solo al aliviador antiinflamatorio
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"Un cambio de paradigma","texto":"Durante años el asma se trató con SABA a demanda. Hoy se sabe que cada rescate debe incluir un antiinflamatorio. El aliviador antiinflamatorio cambió la forma de tratar el asma."},"objetivos":["Reconocer el cambio de paradigma.","Explicar el aliviador antiinflamatorio.","Aplicar la vía 1 de GINA.","Educar sobre el nuevo esquema."],"conceptos":[{"icono":"ShieldCheck","termino":"AIR","definicion":"Rescate antiinflamatorio."},{"icono":"Pill","termino":"ICS-formoterol","definicion":"Combinación de rescate."},{"icono":"Repeat","termino":"MART","definicion":"Mantenimiento y rescate."},{"icono":"AlertTriangle","termino":"SABA solo","definicion":"Práctica que ya no se recomienda."}],"secciones":[{"titulo":"El problema del SABA solo","parrafos":["El uso de SABA solo no trata la inflamación y se asocia con exacerbaciones y muerte. El sobreuso refleja mal control y aumenta el riesgo. Durante años, el tratamiento se centró en aliviar el síntoma sin tratar la causa.","El cambio hacia el aliviador antiinflamatorio busca que cada rescate aporte corticoide y reduzca el riesgo."]},{"titulo":"La vía 1","parrafos":["En adultos y adolescentes, la vía 1 de GINA usa ICS-formoterol como rescate antiinflamatorio en todos los pasos. En los pasos 1-2 se usa a demanda; en el paso 3, MART con una inhalación mañana y noche más rescate; en el paso 4, dosis media.","La ventaja es simplificar el esquema y asegurar el corticoide en cada alivio. La desventaja es que exige educación clara para no confundir mantenimiento y rescate."]},{"titulo":"Aplicación","parrafos":["El QF explica el cambio, verifica la técnica y revisa los límites. La vía 2 sigue siendo una alternativa con ICS-SABA o SABA, pero la vía 1 es la preferida.","La educación y el seguimiento son clave para que el paciente use el inhalador correctamente. El cambio requiere explicar por qué el SABA solo ya no se recomienda, cómo funciona el alivio antiinflamatorio y cuáles son los límites. La revisión de la técnica y la verificación de la comprensión son parte de la intervención. En Colombia, el acceso a las combinaciones y la cobertura del PBS condicionan la implementación; el QF busca alternativas dentro del esquema. La documentación de la educación y del plan permite evaluar la respuesta. La revisión de las creencias y del miedo al corticoide es parte del proceso. La familia o el cuidador también recibe instrucción."]}],"errores":[{"error":"Mantener SABA solo.","correccion":"Riesgo de exacerbaciones."},{"error":"No explicar el cambio.","correccion":"El paciente se confunde."},{"error":"No revisar la técnica.","correccion":"El fármaco no llega."}],"comprueba":[{"pregunta":"¿Qué es el AIR?","respuesta":"Rescate antiinflamatorio."},{"pregunta":"¿Qué combinación se usa?","respuesta":"ICS-formoterol."},{"pregunta":"¿Qué vía es la preferida?","respuesta":"La vía 1."}],"resumen":["El SABA solo ya no se recomienda.","El aliviador antiinflamatorio cambió el manejo.","La vía 1 simplifica el esquema.","La educación es clave."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"}],"imagenes":[{"ubicacion":"Unidad 2","descripcion":"Del SABA solo al aliviador antiinflamatorio.","alt":"Aliviador antiinflamatorio en asma"}],"keywords":["aliviador antiinflamatorio","air","gina vía 1","saba solo"],"mapa":{"centro":"Aliviador antiinflamatorio","ramas":[{"titulo":"Antes","icono":"Zap","nodos":["SABA solo","Riesgo","Sobreuso"]},{"titulo":"Ahora","icono":"ShieldCheck","nodos":["AIR","ICS-formoterol","MART"]},{"titulo":"Vía 1","icono":"Route","nodos":["Pasos 1-2","Paso 3","Paso 4"]},{"titulo":"Educación","icono":"Users","nodos":["Uso","Límites","Técnica"]}]},"proceso":{"titulo":"Explicar el cambio","intro":"","pasos":[{"titulo":"Contexto","detalle":"Por qué no SABA solo.","icono":"BookOpen","evidencia":"Educación."},{"titulo":"Esquema","detalle":"Vía y paso.","icono":"Route","evidencia":"Plan."},{"titulo":"Técnica","detalle":"Uso y límites.","icono":"Eye","evidencia":"Demostración."},{"titulo":"Adherencia","detalle":"Mantenimiento.","icono":"CalendarClock","evidencia":"Registro."},{"titulo":"Seguir","detalle":"Control y ajuste.","icono":"Repeat","evidencia":"Consulta."}]},"caso":{"titulo":"SABA a demanda","contexto":"Paciente que solo usa salbutamol cuando tiene síntomas.","pregunta":"¿Qué cambio se propone?","opciones":[{"texto":"Mantener el SABA solo.","correcta":false,"retro":"No trata la inflamación."},{"texto":"Aliviador antiinflamatorio.","correcta":true,"retro":"Cada rescate aporta ICS."},{"texto":"Suspender todo.","correcta":false,"retro":"Empeora."}]}}$j$::jsonb;
