  -- 09. GINA Track 1: MART con budesonida-formoterol y por qué no SABA solo
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Un inhalador para todo","texto":"El MART usa budesonida-formoterol para mantenimiento y rescate. Simplifica el esquema y asegura el corticoide en cada alivio. La educación sobre los límites es indispensable."},"objetivos":["Explicar el MART.","Aplicar la dosis y los límites.","Reconocer la evidencia.","Educar al paciente."],"conceptos":[{"icono":"Repeat","termino":"MART","definicion":"Mantenimiento y rescate."},{"icono":"ShieldCheck","termino":"ICS-formoterol","definicion":"Combinación de la vía 1."},{"icono":"Calculator","termino":"Límites","definicion":"Máximo por ocasión y por día."},{"icono":"AlertTriangle","termino":"Confusión","definicion":"Error entre mantenimiento y rescate."}],"secciones":[{"titulo":"Qué es el MART","parrafos":["El MART usa budesonida-formoterol para mantenimiento y rescate. En el paso 3, una inhalación mañana y noche más una a necesidad. En el paso 4, dos inhalaciones mañana y noche más una a necesidad.","La ventaja es que cada rescate aporta corticoide y se simplifica el esquema. La evidencia muestra menos exacerbaciones frente a ICS-LABA fijo con SABA."]},{"titulo":"Límites y seguridad","parrafos":["No se deben superar seis inhalaciones en una sola ocasión. Normalmente no más de ocho al día, hasta doce por tiempo limitado. Si se necesitan más de doce en 24 horas, el paciente debe consultar.","La confusión entre mantenimiento y rescate es el error más frecuente. El paciente debe saber que el mantenimiento no se omite y que el mismo inhalador cumple dos funciones."]},{"titulo":"Educación","parrafos":["El QF demuestra la técnica, explica los límites y verifica la comprensión. El dispositivo de polvo seco exige inhalar fuerte y no exhalar dentro. El enjuague después de las dosis de mantenimiento reduce la candidiasis.","La revisión del contador y la fecha de vencimiento es parte de la dispensación. La educación y el seguimiento mejoran la adherencia. El paciente debe saber cuántas inhalaciones usar en el mantenimiento y cuántas en el rescate, y cuándo consultar. La revisión del contador evita quedarse sin medicamento. La técnica se verifica en cada visita y después de un cambio de dispositivo. La educación debe adaptarse a la edad y al nivel de comprensión. La familia o el cuidador también recibe instrucción. La revisión de la comprensión con teach-back confirma que el paciente sabe cuándo usar el mantenimiento y cuándo el rescate."]}],"errores":[{"error":"No explicar los dos usos.","correccion":"Se usa mal el rescate."},{"error":"No fijar límites.","correccion":"El paciente no sabe cuándo consultar."},{"error":"No revisar la técnica.","correccion":"El polvo seco exige inhalar fuerte."}],"comprueba":[{"pregunta":"¿Qué es el MART?","respuesta":"Mantenimiento y rescate con el mismo inhalador."},{"pregunta":"¿Máximo por ocasión?","respuesta":"Seis inhalaciones."},{"pregunta":"¿Cuándo consultar?","respuesta":"Más de doce en 24 horas o sin mejoría."}],"resumen":["El MART simplifica el esquema.","Cada rescate aporta corticoide.","Los límites son parte de la educación.","La técnica y el seguimiento son clave."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"},{"cita":"AEMPS-CIMA. Ficha técnica de Symbicort Turbuhaler 160/4,5 microgramos. Revisión febrero 2021.","url":"https://cima.aemps.es/cima/dochtml/ft/63958/FT_63958.html"}],"imagenes":[{"ubicacion":"GINA Track 1","descripcion":"MART con budesonida-formoterol.","alt":"MART en asma"}],"keywords":["mart","budesonida formoterol","gina track 1","asma"],"mapa":{"centro":"MART","ramas":[{"titulo":"Mantenimiento","icono":"CalendarClock","nodos":["Mañana","Noche","Todos los días"]},{"titulo":"Rescate","icono":"Zap","nodos":["1 a necesidad","Máximo","Consultar"]},{"titulo":"Evidencia","icono":"LineChart","nodos":["Menos exacerbaciones","Menos SABA"]},{"titulo":"Educación","icono":"Users","nodos":["Dos usos","Límites","Técnica"]}]},"proceso":{"titulo":"Educar en MART","intro":"","pasos":[{"titulo":"Explicar","detalle":"Dos funciones.","icono":"BookOpen","evidencia":"Consejería."},{"titulo":"Demostrar","detalle":"Técnica y enjuague.","icono":"Eye","evidencia":"Práctica."},{"titulo":"Fijar","detalle":"Dosis de mantenimiento.","icono":"CalendarClock","evidencia":"Horario."},{"titulo":"Limitar","detalle":"Máximo diario.","icono":"Calculator","evidencia":"Plan."},{"titulo":"Verificar","detalle":"Comprensión y uso.","icono":"ClipboardCheck","evidencia":"Control."}]},"caso":{"titulo":"Más de doce al día","contexto":"Paciente con MART que usa más de doce inhalaciones al día y no mejora.","pregunta":"¿Qué debe hacer?","opciones":[{"texto":"Esperar unos días.","correcta":false,"retro":"Debe consultar."},{"texto":"Consultar por atención urgente.","correcta":true,"retro":"Supera el límite."},{"texto":"Duplicar el mantenimiento.","correcta":false,"retro":"No es seguro."}]}}$j$::jsonb;
