  -- 10. Escalonamiento, desescalamiento, niños y la GPC de asma MinSalud (2013)
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Subir y bajar con criterio","texto":"El tratamiento del asma se ajusta por pasos. Subir sin revisar la técnica y la adherencia es un error; bajar sin control también. Las guías y la edad del paciente orientan la decisión."},"objetivos":["Aplicar el escalonamiento.","Reconocer el desescalamiento.","Ajustar en niños.","Comparar con la GPC colombiana."],"conceptos":[{"icono":"Route","termino":"Escalón","definicion":"Nivel de tratamiento."},{"icono":"Repeat","termino":"Desescalar","definicion":"Reducir tras buen control."},{"icono":"Users","termino":"Niños","definicion":"Dosis y dispositivos adaptados."},{"icono":"BookOpen","termino":"GPC","definicion":"Guía colombiana de asma."}],"secciones":[{"titulo":"Escalonamiento y desescalamiento","parrafos":["El tratamiento se ajusta según el control. Antes de subir un paso se revisan la técnica, la adherencia, las comorbilidades y los desencadenantes. Si el control es bueno durante dos a tres meses, se puede considerar bajar un paso, sin suspender por completo el ICS en adultos y adolescentes.","La reducción debe ser gradual y con seguimiento. La suspensión brusca del ICS aumenta el riesgo de exacerbaciones."]},{"titulo":"Niños","parrafos":["En niños de 6 a 11 años, los pasos y los dispositivos se adaptan a la edad. La vía 1 incluye AIR con ICS-formoterol en los pasos 1 y 2. La técnica con cámara espaciadora es fundamental. El crecimiento y los efectos sistémicos se monitorizan.","La GPC colombiana de asma de 2013 sigue vigente en algunos aspectos, pero debe contrastarse con GINA 2026. La educación de la familia es parte del tratamiento."]},{"titulo":"Aplicación","parrafos":["El QF revisa la coherencia del paso, la técnica y la adherencia. También educa sobre el plan de acción y los signos de alarma. La revisión periódica evita el sobretratamiento y el subtratamiento.","La decisión se comparte con el paciente y la familia. La documentación permite evaluar la respuesta. La GPC colombiana de 2013 y GINA 2026 coinciden en la importancia del control y la educación, aunque difieren en algunos aspectos. La revisión de la evidencia local y la disponibilidad de dispositivos son parte de la decisión. El QF debe evitar el sobretratamiento y el subtratamiento, y acompañar al paciente en cada cambio. La educación sobre el plan de acción y los signos de alarma se refuerza en cada contacto."]}],"errores":[{"error":"Subir sin revisar técnica.","correccion":"Se sobretrata."},{"error":"Suspender el ICS de golpe.","correccion":"Riesgo de crisis."},{"error":"No adaptar el dispositivo al niño.","correccion":"No llega el fármaco."}],"comprueba":[{"pregunta":"¿Qué se revisa antes de subir?","respuesta":"Técnica y adherencia."},{"pregunta":"¿Cuándo se baja?","respuesta":"Tras 2-3 meses de control."},{"pregunta":"¿Qué guía colombiana existe?","respuesta":"La GPC de asma 2013."}],"resumen":["El tratamiento se ajusta por pasos.","Antes de subir se revisan técnica y adherencia.","El desescalamiento es gradual.","La GPC y GINA se complementan."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"},{"cita":"Ministerio de Salud y Protección Social. Guía de práctica clínica de asma (Guía n.º 01). Bogotá; 2013.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/INEC/IETS/GPC_Comp_Asma.pdf"}],"imagenes":[{"ubicacion":"Escalonamiento","descripcion":"Pasos y ajuste del tratamiento.","alt":"Escalonamiento del asma"}],"keywords":["escalonamiento asma","desescalamiento","gpc asma","niños asma"],"mapa":{"centro":"Escalonamiento","ramas":[{"titulo":"Subir","icono":"LineChart","nodos":["Control","Técnica","Adherencia"]},{"titulo":"Bajar","icono":"Repeat","nodos":["2-3 meses","Sin crisis","Vigilar"]},{"titulo":"Niños","icono":"Users","nodos":["Dispositivo","Dosis","Crecimiento"]},{"titulo":"GPC","icono":"BookOpen","nodos":["MinSalud 2013","Colombia","Brechas"]}]},"proceso":{"titulo":"Ajustar el paso","intro":"","pasos":[{"titulo":"Evaluar","detalle":"Control y adherencia.","icono":"ClipboardList","evidencia":"ACT."},{"titulo":"Revisar","detalle":"Técnica y comorbilidad.","icono":"Eye","evidencia":"Entrevista."},{"titulo":"Subir","detalle":"Si no hay control.","icono":"LineChart","evidencia":"Plan."},{"titulo":"Bajar","detalle":"Si hay buen control.","icono":"Repeat","evidencia":"Decisión."},{"titulo":"Seguir","detalle":"2-3 meses.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Buen control","contexto":"Paciente con asma bien controlada durante tres meses con ICS.","pregunta":"¿Qué se considera?","opciones":[{"texto":"Bajar un paso con seguimiento.","correcta":true,"retro":"Se puede desescalar."},{"texto":"Suspender el ICS de golpe.","correcta":false,"retro":"Riesgo de exacerbación."},{"texto":"Duplicar la dosis.","correcta":false,"retro":"No es necesario."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Escalonamiento, desescalamiento, niños y la GPC de asma MinSalud (2013)$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Escalonamiento, desescalamiento, niños y la GPC de asma MinSalud (2013)$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  IF v_n > 0 THEN
    INSERT INTO aula_republicaciones_aprobadas (course_id, aprobado_por, nota)
    SELECT v_curso, 'Dirección académica de Edvanta', 'Clases ampliadas con experiencia interactiva (156_experiencias_farmacologia_respiratoria_1.sql).'
     WHERE EXISTS (SELECT 1 FROM aula_courses WHERE id = v_curso AND current_version_id IS NOT NULL);
  END IF;

  RAISE NOTICE 'Experiencias de %: % clases.', $t$Curso de Farmacología Respiratoria$t$, v_n;
END $exp$;
